using System.Collections;
using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

namespace Intropy.Topology;

/// <summary>
/// Central serialization policy for topology records. One shared
/// <see cref="JsonSerializerOptions"/> keeps every entity consistent: camelCase
/// keys, enums as their lowercase machine strings, and no noise from unset
/// optional fields or empty collections.
/// </summary>
public static class TopologyJson
{
    /// <summary>The topology schema version this library emits.</summary>
    public const int SchemaVersion = 1;

    /// <summary>The serializer options used by <c>ToJson</c>/<c>Save</c>.</summary>
    public static JsonSerializerOptions Options { get; } = Build();

    private static JsonSerializerOptions Build()
    {
        var options = new JsonSerializerOptions
        {
            PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
            DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
            WriteIndented = true,
            TypeInfoResolver = new DefaultJsonTypeInfoResolver
            {
                Modifiers = { IgnoreEmptyCollections },
            },
        };
        // Enum members carry explicit [JsonStringEnumMemberName] values, so no
        // naming policy is needed here.
        options.Converters.Add(new JsonStringEnumConverter());
        return options;
    }

    /// <summary>
    /// Omits collection properties that are empty, mirroring Go's
    /// <c>omitempty</c> so a record only lists what it actually declares.
    /// </summary>
    private static void IgnoreEmptyCollections(JsonTypeInfo typeInfo)
    {
        foreach (var property in typeInfo.Properties)
        {
            if (property.PropertyType != typeof(string) &&
                typeof(IEnumerable).IsAssignableFrom(property.PropertyType))
            {
                property.ShouldSerialize = static (_, value) => value is ICollection { Count: > 0 };
            }
        }
    }
}

using System.Text.Json.Serialization;

namespace Intropy.Topology.Models;

/// <summary>
/// The block type of a <see cref="Component"/>. All three current types are
/// edge blocks that share the same record shape and differ only in
/// responsibility; the enum keeps authoring type-safe while serializing to the
/// lowercase machine strings the topology record uses.
/// </summary>
public enum ComponentType
{
    /// <summary>Pulls data from a source system.</summary>
    [JsonStringEnumMemberName("extractor")]
    Extractor,

    /// <summary>Writes data to a destination system.</summary>
    [JsonStringEnumMemberName("loader")]
    Loader,

    /// <summary>Extracts, transforms, and imports transactional data in one block.</summary>
    [JsonStringEnumMemberName("transactional")]
    TransactionalIntegration,
}

using System.Text.Json.Serialization;

namespace Intropy.Topology.Models;

/// <summary>
/// The kind of infrastructure a <see cref="Resource"/> represents. Only
/// <see cref="Topic"/> is modeled today; Database and connectors follow later.
/// </summary>
public enum ResourceType
{
    /// <summary>A pub/sub topic carrying a data entity.</summary>
    [JsonStringEnumMemberName("topic")]
    Topic,
}

using System.Text.Json.Serialization;

namespace Intropy.Topology.Models;

/// <summary>
/// The direction and nature of an <see cref="Edge"/>. Connector/uses edges
/// arrive with connectors and external catalog references later.
/// </summary>
public enum EdgeKind
{
    /// <summary>A component writes to a topic (component → resource).</summary>
    [JsonStringEnumMemberName("publish")]
    Publish,

    /// <summary>A component reads from a topic (resource → component).</summary>
    [JsonStringEnumMemberName("consume")]
    Consume,
}

using System.Text.Json.Serialization;

namespace Intropy.Topology.Models;

/// <summary>How a component is activated when it is not derivable from edges.</summary>
public enum TriggerKind
{
    /// <summary>Runs on a cron schedule.</summary>
    [JsonStringEnumMemberName("schedule")]
    Schedule,
}

namespace Intropy.Topology.Models;

/// <summary>
/// Records what produced a topology record, so a stale file can be traced back
/// to the tool and commit that generated it.
/// </summary>
public sealed class Generator
{
    /// <summary>The generating tool's name.</summary>
    public string Tool { get; set; } = "Intropy.Topology";

    /// <summary>The generator version, e.g. "0.1.0".</summary>
    public string? Version { get; set; }

    /// <summary>Provenance of the input, e.g. "orders@local" or "integrations@3f9c2e1".</summary>
    public string? Source { get; set; }
}

namespace Intropy.Topology.Models;

/// <summary>A component's activation when it is not derivable from edges.</summary>
public sealed class Trigger
{
    /// <summary>The trigger kind.</summary>
    public TriggerKind Kind { get; set; }

    /// <summary>The cron expression, present when <see cref="Kind"/> is <see cref="TriggerKind.Schedule"/>.</summary>
    public string? Schedule { get; set; }
}

namespace Intropy.Topology.Models;

/// <summary>
/// A deployable block of the system. Prefer building components through
/// <see cref="SystemTopology.AddComponent"/> and the returned builder rather
/// than wiring edges by hand.
/// </summary>
public sealed class Component
{
    /// <summary>The component's unique name within the system.</summary>
    public required string Name { get; set; }

    /// <summary>The block type.</summary>
    public required ComponentType Type { get; set; }

    /// <summary>Integration identifiers, e.g. "int-042" — the Backstage catalog tags.</summary>
    public List<string> Tags { get; } = [];

    /// <summary>The component's directory relative to the system root.</summary>
    public string? Project { get; set; }

    /// <summary>Deployment hint, e.g. "cronjob" or "deployment". Recorded, not interpreted.</summary>
    public string? Workload { get; set; }

    /// <summary>Non-derivable activation; null when a consume edge already implies the trigger.</summary>
    public Trigger? Trigger { get; set; }
}

using System.Text.Json.Serialization;

namespace Intropy.Topology.Models;

/// <summary>
/// Infrastructure the components depend on. The <see cref="Type"/> decides which
/// optional fields apply; for <see cref="ResourceType.Topic"/> those are
/// <see cref="PubSub"/> and <see cref="Entity"/>.
/// </summary>
public sealed class Resource
{
    /// <summary>The resource's unique name within the system.</summary>
    public required string Name { get; set; }

    /// <summary>The resource kind.</summary>
    public required ResourceType Type { get; set; }

    /// <summary>Topic field: the pub/sub broker name carrying the topic.</summary>
    [JsonPropertyName("pubsub")]
    public string? PubSub { get; set; }

    /// <summary>Topic field: the data entity on the topic, e.g. "RawProduct".</summary>
    public string? Entity { get; set; }
}

namespace Intropy.Topology.Models;

/// <summary>
/// A directed relation between two entities. References use the form
/// <c>component:&lt;name&gt;</c> / <c>resource:&lt;name&gt;</c>. Edges are normally
/// produced by the component builder's relationship helpers rather than
/// constructed directly.
/// </summary>
public sealed class Edge
{
    /// <summary>The source entity reference.</summary>
    public required string From { get; set; }

    /// <summary>The destination entity reference.</summary>
    public required string To { get; set; }

    /// <summary>The relation's direction and nature.</summary>
    public required EdgeKind Kind { get; set; }

    /// <summary>The component output port a publish edge leaves through, when relevant.</summary>
    public string? Port { get; set; }
}

namespace Intropy.Topology.Models;

/// <summary>
/// Builds the entity reference strings edges use, keeping the
/// <c>&lt;kind&gt;:&lt;name&gt;</c> convention in one place.
/// </summary>
internal static class Ref
{
    public static string Component(string name) => $"component:{name}";

    public static string Resource(string name) => $"resource:{name}";
}

using Intropy.Topology.Models;

namespace Intropy.Topology.Building;

/// <summary>
/// Fluent helper for a single <see cref="Component"/>. Relationship methods add
/// the corresponding <see cref="Edge"/> to the owning topology, so authors
/// declare flow in terms of the resources involved and never hand-type
/// reference strings.
/// </summary>
public sealed class ComponentBuilder
{
    private readonly SystemTopology _topology;

    internal ComponentBuilder(SystemTopology topology, Component component)
    {
        _topology = topology;
        Component = component;
    }

    /// <summary>The component being built.</summary>
    public Component Component { get; }

    /// <summary>Declares that this component publishes to <paramref name="topic"/>.</summary>
    public ComponentBuilder ProducesTo(Resource topic)
    {
        _topology.Edges.Add(new Edge
        {
            From = Ref.Component(Component.Name),
            To = Ref.Resource(topic.Name),
            Kind = EdgeKind.Publish,
        });
        return this;
    }

    /// <summary>Declares that this component consumes from <paramref name="topic"/>.</summary>
    public ComponentBuilder ConsumesFrom(Resource topic)
    {
        _topology.Edges.Add(new Edge
        {
            From = Ref.Resource(topic.Name),
            To = Ref.Component(Component.Name),
            Kind = EdgeKind.Consume,
        });
        return this;
    }

    /// <summary>Sets a cron schedule trigger on the component.</summary>
    public ComponentBuilder OnSchedule(string cron)
    {
        Component.Trigger = new Trigger { Kind = TriggerKind.Schedule, Schedule = cron };
        return this;
    }

    /// <summary>Adds integration identifier tags to the component.</summary>
    public ComponentBuilder WithTags(params string[] tags)
    {
        Component.Tags.AddRange(tags);
        return this;
    }

    /// <summary>Sets the component's project directory, relative to the system root.</summary>
    public ComponentBuilder InProject(string project)
    {
        Component.Project = project;
        return this;
    }

    /// <summary>Sets the component's deployment workload hint.</summary>
    public ComponentBuilder Workload(string workload)
    {
        Component.Workload = workload;
        return this;
    }
}

using System.Text.Json;
using System.Text.Json.Serialization;
using Intropy.Topology.Building;

namespace Intropy.Topology.Models;

/// <summary>
/// A single integration system's declared topology and the root of a
/// <c>topology.json</c> record. Build it with the authoring helpers
/// (<see cref="AddTopic"/>, <see cref="AddComponent"/>) and serialize with
/// <see cref="ToJson"/> or <see cref="Save"/>.
/// </summary>
public sealed class SystemTopology
{
    /// <summary>Creates a topology for the named system.</summary>
    public SystemTopology(string systemName) => SystemName = systemName;

    /// <summary>The schema version this record conforms to. Always the library's current version.</summary>
    public int SchemaVersion => TopologyJson.SchemaVersion;

    /// <summary>What generated this record.</summary>
    public Generator Generator { get; set; } = new();

    /// <summary>The system's name.</summary>
    public string SystemName { get; set; }

    /// <summary>The owning team, as a Backstage Group ref, e.g. "group:default/team-integration".</summary>
    public string? Owner { get; set; }

    /// <summary>The system's business domain, e.g. "sales".</summary>
    public string? Domain { get; set; }

    /// <summary>The system's components (blocks).</summary>
    public List<Component> Components { get; } = [];

    /// <summary>The infrastructure resources the components use.</summary>
    public List<Resource> Resources { get; } = [];

    /// <summary>Directed data-flow edges between entities.</summary>
    public List<Edge> Edges { get; } = [];

    /// <summary>Adds a topic resource and returns it so components can reference it.</summary>
    public Resource AddTopic(string name, string? entity = null, string? pubsub = null)
    {
        var resource = new Resource
        {
            Name = name,
            Type = ResourceType.Topic,
            Entity = entity,
            PubSub = pubsub,
        };
        Resources.Add(resource);
        return resource;
    }

    /// <summary>Adds a component and returns a builder for wiring its relationships.</summary>
    public ComponentBuilder AddComponent(string name, ComponentType type)
    {
        var component = new Component { Name = name, Type = type };
        Components.Add(component);
        return new ComponentBuilder(this, component);
    }

    /// <summary>Serializes the topology to its <c>topology.json</c> representation.</summary>
    public string ToJson() => JsonSerializer.Serialize(this, TopologyJson.Options);

    /// <summary>Serializes the topology and writes it to <paramref name="path"/>.</summary>
    public void Save(string path) => File.WriteAllText(path, ToJson());
}

using System.Text.Json;
