namespace Intropy.Topology.Tests;

public class EnumSerializationTests
{
    [Theory]
    [InlineData(ComponentType.Extractor, "\"extractor\"")]
    [InlineData(ComponentType.Loader, "\"loader\"")]
    [InlineData(ComponentType.TransactionalIntegration, "\"transactional\"")]
    public void ComponentType_serializes_to_its_machine_string(ComponentType type, string expected)
    {
        Assert.Equal(expected, JsonSerializer.Serialize(type, TopologyJson.Options));
    }

    [Fact]
    public void ResourceType_topic_serializes_lowercase()
    {
        Assert.Equal("\"topic\"", JsonSerializer.Serialize(ResourceType.Topic, TopologyJson.Options));
    }

    [Theory]
    [InlineData(EdgeKind.Publish, "\"publish\"")]
    [InlineData(EdgeKind.Consume, "\"consume\"")]
    public void EdgeKind_serializes_lowercase(EdgeKind kind, string expected)
    {
        Assert.Equal(expected, JsonSerializer.Serialize(kind, TopologyJson.Options));
    }

    [Fact]
    public void TriggerKind_schedule_serializes_lowercase()
    {
        Assert.Equal("\"schedule\"", JsonSerializer.Serialize(TriggerKind.Schedule, TopologyJson.Options));
    }
}

using Intropy.Topology.Models;

namespace Intropy.Topology.Tests;

public class BuilderTests
{
    [Fact]
    public void AddTopic_registers_a_topic_resource_and_returns_it()
    {
        var topology = new SystemTopology("sales");

        var topic = topology.AddTopic("orders", entity: "Order", pubsub: "pubsub");

        Assert.Same(topic, Assert.Single(topology.Resources));
        Assert.Equal("orders", topic.Name);
        Assert.Equal(ResourceType.Topic, topic.Type);
        Assert.Equal("Order", topic.Entity);
        Assert.Equal("pubsub", topic.PubSub);
    }

    [Fact]
    public void AddComponent_registers_the_component()
    {
        var topology = new SystemTopology("sales");

        var builder = topology.AddComponent("erp-loader", ComponentType.Loader);

        Assert.Same(builder.Component, Assert.Single(topology.Components));
        Assert.Equal("erp-loader", builder.Component.Name);
        Assert.Equal(ComponentType.Loader, builder.Component.Type);
    }

    [Fact]
    public void ProducesTo_adds_a_publish_edge_from_component_to_topic()
    {
        var topology = new SystemTopology("sales");
        var topic = topology.AddTopic("product-raw");

        topology.AddComponent("pim-extractor", ComponentType.Extractor).ProducesTo(topic);

        var edge = Assert.Single(topology.Edges);
        Assert.Equal("component:pim-extractor", edge.From);
        Assert.Equal("resource:product-raw", edge.To);
        Assert.Equal(EdgeKind.Publish, edge.Kind);
    }

    [Fact]
    public void ConsumesFrom_adds_a_consume_edge_from_topic_to_component()
    {
        var topology = new SystemTopology("sales");
        var topic = topology.AddTopic("product-raw");

        topology.AddComponent("erp-loader", ComponentType.Loader).ConsumesFrom(topic);

        var edge = Assert.Single(topology.Edges);
        Assert.Equal("resource:product-raw", edge.From);
        Assert.Equal("component:erp-loader", edge.To);
        Assert.Equal(EdgeKind.Consume, edge.Kind);
    }

    [Fact]
    public void OnSchedule_sets_a_schedule_trigger()
    {
        var topology = new SystemTopology("sales");

        var builder = topology.AddComponent("pim-extractor", ComponentType.Extractor)
            .OnSchedule("*/15 * * * *");

        Assert.NotNull(builder.Component.Trigger);
        Assert.Equal(TriggerKind.Schedule, builder.Component.Trigger!.Kind);
        Assert.Equal("*/15 * * * *", builder.Component.Trigger.Schedule);
    }

    [Fact]
    public void Builder_methods_chain_and_apply_metadata()
    {
        var topology = new SystemTopology("sales");

        var component = topology
            .AddComponent("pim-extractor", ComponentType.Extractor)
            .WithTags("int-042", "products")
            .InProject("pim-extractor")
            .Workload("cronjob")
            .Component;

        Assert.Equal(["int-042", "products"], component.Tags);
        Assert.Equal("pim-extractor", component.Project);
        Assert.Equal("cronjob", component.Workload);
    }
}

using System.Text.Json.Nodes;
using Intropy.Topology.Models;

namespace Intropy.Topology.Tests;

public class SerializationTests
{
    [Fact]
    public void SchemaVersion_is_always_one()
    {
        var json = JsonNode.Parse(new SystemTopology("sales").ToJson())!;

        Assert.Equal(1, (int)json["schemaVersion"]!);
    }

    [Fact]
    public void Empty_collections_are_omitted()
    {
        var json = JsonNode.Parse(new SystemTopology("sales").ToJson())!.AsObject();

        Assert.False(json.ContainsKey("components"));
        Assert.False(json.ContainsKey("resources"));
        Assert.False(json.ContainsKey("edges"));
