        Assert.Equal("order-fulfillment", system.Topology.SystemName);
    }

    [Fact]
    public void WithOwner_and_InDomain_set_system_metadata()
    {
        var system = SystemBuilder.Create("order-fulfillment")
            .WithOwner("group:default/team-integration")
            .InDomain("fulfillment");

        Assert.Equal("group:default/team-integration", system.Topology.Owner);
        Assert.Equal("fulfillment", system.Topology.Domain);
    }

    [Fact]
    public void AddTopic_registers_a_topic_resource_and_returns_it()
    {
        var system = SystemBuilder.Create("sales");

        var topic = system.AddTopic("orders", entity: "Order", pubsub: "pubsub");

        Assert.Same(topic, Assert.Single(system.Topology.Resources));
        Assert.Equal("orders", topic.Name);
        Assert.Equal(ResourceType.Topic, topic.Type);
        Assert.Equal("Order", topic.Entity);
        Assert.Equal("pubsub", topic.PubSub);
    }

    [Theory]
    [InlineData(ComponentType.Extractor)]
    [InlineData(ComponentType.Loader)]
    [InlineData(ComponentType.TransactionalIntegration)]
    public void Block_helpers_add_a_component_of_the_right_type(ComponentType expected)
    {
        var system = SystemBuilder.Create("sales");

        var builder = expected switch
        {
            ComponentType.Extractor => system.AddExtractor("x"),
            ComponentType.Loader => system.AddLoader("x"),
            _ => system.AddTransactionalIntegration("x"),
        };

        Assert.Same(builder.Component, Assert.Single(system.Topology.Components));
        Assert.Equal("x", builder.Component.Name);
        Assert.Equal(expected, builder.Component.Type);
    }

    [Fact]
    public void Publishes_adds_a_publish_edge_from_component_to_topic()
    {
        var system = SystemBuilder.Create("sales");
        var topic = system.AddTopic("product-raw");

        system.AddExtractor("pim-extractor").Publishes(topic);

        var edge = Assert.Single(system.Topology.Edges);
        Assert.Equal("component:pim-extractor", edge.From);
        Assert.Equal("resource:product-raw", edge.To);
        Assert.Equal(EdgeKind.Publish, edge.Kind);
    }

    [Fact]
    public void Consumes_adds_a_consume_edge_from_topic_to_component()
    {
        var system = SystemBuilder.Create("sales");
        var topic = system.AddTopic("product-raw");

        system.AddLoader("erp-loader").Consumes(topic);

        var edge = Assert.Single(system.Topology.Edges);
        Assert.Equal("resource:product-raw", edge.From);
        Assert.Equal("component:erp-loader", edge.To);
        Assert.Equal(EdgeKind.Consume, edge.Kind);
    }

    [Fact]
    public void Wiring_to_a_predefined_topic_registers_it_once()
    {
        // A topic reference declared outside the builder (e.g. a static holder).
        var raw = Resource.Topic("stock-raw", entity: "RawStock", pubsub: "pubsub");
        var system = SystemBuilder.Create("order-fulfillment");

        system.AddExtractor("stock-extractor").Publishes(raw);
        system.AddLoader("erp-loader").Consumes(raw);

        Assert.Same(raw, Assert.Single(system.Topology.Resources));
        Assert.Equal(2, system.Topology.Edges.Count);
    }

    [Fact]
    public void OnSchedule_sets_a_schedule_trigger()
    {
        var system = SystemBuilder.Create("sales");

        var builder = system.AddExtractor("pim-extractor").OnSchedule("*/15 * * * *");

        Assert.NotNull(builder.Component.Trigger);
        Assert.Equal(TriggerKind.Schedule, builder.Component.Trigger!.Kind);
        Assert.Equal("*/15 * * * *", builder.Component.Trigger.Schedule);
    }

    [Fact]
    public void Builder_methods_chain_and_apply_metadata()
    {
        var system = SystemBuilder.Create("sales");

        var component = system
            .AddExtractor("pim-extractor")
            .WithTags("int-042", "products")
            .InProject("pim-extractor")
            .Workload("cronjob")
            .Component;

        Assert.Equal(["int-042", "products"], component.Tags);
        Assert.Equal("pim-extractor", component.Project);
        Assert.Equal("cronjob", component.Workload);
    }
}

